SELECT ACCT_NO, BUSI_ACCT_NO,
rtrim(xmlagg(xmlparse(content PORTFOLIO_ID||',' wellformed) order by PORTFOLIO_ID).getclobval(), ',') as PORTFOLIO_ID, rtrim(xmlagg(xmlparse(content PORTFOLIO_NAME||',' wellformed) order by PORTFOLIO_ID).getclobval(), ',') as PORTFOLIO_NAME, COUNT(PORTFOLIO_ID) unmatchedNum, sum(matched) matchNum /*多级法人改造 add by caojin 20200701 start */ ,seqNo /*多级法人改造 add by caojin 20200701 end */ from ( SELECT DISTINCT ACCT_NO, BUSI_ACCT_NO, PORTFOLIO_ID, PORTFOLIO_NAME, case when MATCH_SEQNO is null then count(1) else 0 end unmatch, case when MATCH_SEQNO is not null then count(1) else 0 end matched /*多级法人改造 add by caojin 20200701 start */ ,seqNo /*多级法人改造 add by caojin 20200701 end */ FROM ( SELECT T1.ACCT_NO, nvl(t3.BUSI_ACCT_NO, t3.ACCT_NO) BUSI_ACCT_NO, t2.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO /*多级法人改造 add by caojin 20200701 start */ ,T3.SEQ_NO seqNo /*多级法人改造 add by caojin 20200701 end */ FROM TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TT ON TT.P_TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID left join PTL_CAPACCT_INFO T1 ON T4.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO P3 ON P3.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON TT.TOTLE_TRADE_ID = T7.SYS_TRADE_ID or T4.TOTLE_TRADE_ID = T7.SYS_TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY
LEFT JOIN STL_PAY_ORDERS SPO ON T4.TOTLE_TRADE_ID = SPO.TRADE_ID OR TT.TOTLE_TRADE_ID = SPO.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID WHERE T1.ACCT_TYPE = #{A01} AND SPO.MY_ACCT_NO IS NOT NULL AND (SPO.COUNTER_ACCT_NO IS NULL OR SPO.MY_ACCT_NO != SPO.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND ( (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE01}, #{PA_BUSINESS_TYPE02}, #{PA_BUSINESS_TYPE04}, #{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE44}, #{PA_BUSINESS_TYPE45}, #{PA_BUSINESS_TYPE46}, #{PA_BUSINESS_TYPE47}, #{PA_BUSINESS_TYPE48}, #{PA_BUSINESS_TYPE49}, #{PA_BUSINESS_TYPE50}, #{PA_BUSINESS_TYPE38}, #{PA_BUSINESS_TYPE39}, #{PA_BUSINESS_TYPE40}, #{PA_BUSINESS_TYPE41}, #{PA_BUSINESS_TYPE144}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01'))/*非通道或逐笔通道*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE34}, #{PA_BUSINESS_TYPE18}) AND FPA.PAY_TYPE IS NULL) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE77}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}))/*逐笔划款: 银行间买断式逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE51}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}, #{TP03}, #{TP04}) AND fpt.TYPE_6 = 'H01')/*逐笔划款: 银行间/交易所质押式（协议式）逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01') AND SSAI.TRADE_PLACE IN (#{TP01}))/*直投/逐笔划款：银行间债券（收息、还本、到期）*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP03}, #{TP04}))/*逐笔划款: 交易所债券（收息、还本、到期）*/ OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13} ) AND SPO.PS = #{PS01}) )
null) or T1.ACCT_NO in (
#{item}
) AND EXISTS (SELECT 1 from STL_PAY_ORDERS T6 WHERE T4.TOTLE_TRADE_ID = T6.TRADE_ID AND (T6.COUNTER_ACCT_NO IS NULL OR T6.MY_ACCT_NO != T6.COUNTER_ACCT_NO)
null) OR T6.MY_ACCT_NO in (
#{item}
)
UNION ALL
SELECT T1.ACCT_NO, nvl(t3.BUSI_ACCT_NO, t3.ACCT_NO) BUSI_ACCT_NO, t2.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO /*多级法人改造 add by caojin 20200701 start */ ,T3.SEQ_NO seqNo /*多级法人改造 add by caojin 20200701 end */ FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT ON TT.P_TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID left join PTL_CAPACCT_INFO T1 ON T4.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO P3 ON P3.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON TT.TOTLE_TRADE_ID = T7.SYS_TRADE_ID or T4.TOTLE_TRADE_ID = T7.SYS_TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY
LEFT JOIN WFL_STL_PAY_ORDERS SPO ON T4.TOTLE_TRADE_ID = SPO.TRADE_ID OR TT.TOTLE_TRADE_ID = SPO.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID LEFT JOIN SYS_WFL_BUSINESS_LIST T9 ON
(T4.TOTLE_TRADE_ID = T9.TRADE_ID and t9.action_type in (#{new}, 'modify')) OR
(T4.P_TRADE_ID = T9.TRADE_ID and T9.action_type IN (#{revoke},'delete')) LEFT JOIN SYS_WFL_BUSINESS_NODE T10 ON T9.SEQ_NO = T10.SEQ_NO WHERE T1.ACCT_TYPE = #{A01} AND SPO.MY_ACCT_NO IS NOT NULL AND (SPO.COUNTER_ACCT_NO IS NULL OR SPO.MY_ACCT_NO != SPO.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND NOT EXISTS (SELECT 1 FROM SYS_WFL_BUSINESS_NODE TT WHERE TT.SEQ_NO = T9.SEQ_NO AND TT.HIS_NO > T10.HIS_NO) AND (T10.NODE_ID IS NULL OR T10.NODE_ID = #{BACK_OPERATOR} OR T10.NODE_ID = #{BACK_CHECKER}) AND (T9.PROCESS_STATE != 'END' or T9.PROCESS_STATE is null) AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND ( (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE01}, #{PA_BUSINESS_TYPE02}, #{PA_BUSINESS_TYPE04}, #{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE44}, #{PA_BUSINESS_TYPE45}, #{PA_BUSINESS_TYPE46}, #{PA_BUSINESS_TYPE47}, #{PA_BUSINESS_TYPE48}, #{PA_BUSINESS_TYPE49}, #{PA_BUSINESS_TYPE50}, #{PA_BUSINESS_TYPE38}, #{PA_BUSINESS_TYPE39}, #{PA_BUSINESS_TYPE40}, #{PA_BUSINESS_TYPE41}, #{PA_BUSINESS_TYPE144}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01'))/*非通道或逐笔通道*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE34}, #{PA_BUSINESS_TYPE18}) AND FPA.PAY_TYPE IS NULL) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE77}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}))/*逐笔划款: 银行间买断式逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE51}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}, #{TP03}, #{TP04}) AND fpt.TYPE_6 = 'H01')/*逐笔划款: 银行间/交易所质押式（协议式）逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01') AND SSAI.TRADE_PLACE IN (#{TP01}))/*直投/逐笔划款：银行间债券（收息、还本、到期）*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP03}, #{TP04}))/*逐笔划款: 交易所债券（收息、还本、到期）*/ OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13} ) AND SPO.PS = #{PS01}) )
null) or T1.ACCT_NO in (
#{item}
) AND EXISTS (SELECT 1 from STL_PAY_ORDERS T6 WHERE T4.TOTLE_TRADE_ID = T6.TRADE_ID AND (T6.COUNTER_ACCT_NO IS NULL OR T6.MY_ACCT_NO != T6.COUNTER_ACCT_NO) #{item})
UNION ALL
SELECT T1.ACCT_NO, nvl(t3.BUSI_ACCT_NO, t3.ACCT_NO) BUSI_ACCT_NO, t2.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO /*多级法人改造 add by caojin 20200701 start */ ,T3.SEQ_NO seqNo /*多级法人改造 add by caojin 20200701 end */ FROM TRD_PRODUCT_DEAL T4 LEFT JOIN PA_TRD_PRODUCT_DEAL T5 ON T4.TRADE_ID = T5.TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD T8 ON T4.TRADE_ID = T8.TRADE_ID left join PTL_CAPACCT_INFO T1 ON T8.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO P3 ON P3.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON T4.TRADE_ID = T7.SYS_TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY
LEFT JOIN STL_PAY_ORDERS SPO ON T4.TRADE_ID = SPO.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID /*通道交易*/ WHERE T1.ACCT_TYPE = #{A01} AND SPO.MY_ACCT_NO IS NOT NULL AND (SPO.COUNTER_ACCT_NO IS NULL OR SPO.MY_ACCT_NO != SPO.COUNTER_ACCT_NO) AND T8.PORTFOLIO_ID IS NOT NULL AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND ((T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE56}, #{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67}, #{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE61}, #{PA_BUSINESS_TYPE62}, #{PA_BUSINESS_TYPE64}, #{PA_BUSINESS_TYPE87}, #{PA_BUSINESS_TYPE125}) and (FPA.PAY_TYPE = '01' or FPA.FINPROD_ID IS NULL)) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE14}, #{PA_BUSINESS_TYPE13}, #{PA_BUSINESS_TYPE15}) AND FPA.PAY_TYPE IS NULL) /*直投：拆入和特殊目的载体拆入首期，存放同业跨托管户卖出、同业借款跨托管户卖出、项目类资产跨托管户卖出、计划类利率型资产跨托管户卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE10}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01},#{TP03}, #{TP04}))/*逐笔划款: 银行间/交易所债券卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE74}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}))/*逐笔划款: 银行间买断式正回购首期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND T4.PS = #{T39} AND SSAI.TRADE_PLACE IN (#{TP01}) AND FPA.PAY_TYPE IS NULL)/*直投：银行间债券行权-赎回*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款的通道交易：银行间/交易所行权-赎回、银行间/交易所行权-回售*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE20}) AND FPA.PAY_TYPE = '01' AND fpt.TYPE_6 = 'H01' AND SSAI.TRADE_PLACE IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款: 银行间/交易所质押式（协议式）正回购首期*/ OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13} ) AND SPO.PS = #{PS01}) )
null) or T1.ACCT_NO in (
#{item}
) AND EXISTS (SELECT 1 from STL_PAY_ORDERS T6 WHERE T4.TRADE_ID = T6.TRADE_ID AND (T6.COUNTER_ACCT_NO IS NULL OR T6.MY_ACCT_NO != T6.COUNTER_ACCT_NO) #{item})
UNION ALL
SELECT T1.ACCT_NO, nvl(t3.BUSI_ACCT_NO, t3.ACCT_NO) BUSI_ACCT_NO, t2.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO /*多级法人改造 add by caojin 20200701 start */ ,T3.SEQ_NO seqNo /*多级法人改造 add by caojin 20200701 end */ FROM WFL_TRD_PRODUCT_DEAL T4 LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL T5 ON T4.TRADE_ID = T5.TRADE_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T8 ON T4.TRADE_ID = T8.TRADE_ID left join PTL_CAPACCT_INFO T1 ON T8.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO P3 ON P3.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON T4.TRADE_ID = T7.SYS_TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY
LEFT JOIN WFL_STL_PAY_ORDERS SPO ON T4.TRADE_ID = SPO.TRADE_ID LEFT JOIN WFL_TRD_PRODUCT_DEAL PT ON (T4.B_TRADE_ID = PT.P_TRADE_ID or T4.B_TRADE_ID = pt.TRADE_ID) LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID /*通道交易*/ LEFT JOIN SYS_WFL_BUSINESS_LIST T9 ON
(T4.TRADE_ID = T9.TRADE_ID and t9.action_type in (#{new}, 'modify')) OR
(T4.P_TRADE_ID = T9.TRADE_ID and T9.action_type IN (#{revoke},'delete')) LEFT JOIN SYS_WFL_BUSINESS_NODE T10 ON T9.SEQ_NO = T10.SEQ_NO WHERE T1.ACCT_TYPE = #{A01} AND SPO.MY_ACCT_NO IS NOT NULL AND PT.TRADE_ID IS NULL AND NOT EXISTS (SELECT 1 FROM SYS_WFL_BUSINESS_NODE TT WHERE TT.SEQ_NO = T9.SEQ_NO AND TT.HIS_NO > T10.HIS_NO) and (T10.NODE_ID IS NULL OR T10.NODE_ID = #{BACK_OPERATOR} OR T10.NODE_ID = #{BACK_CHECKER}) AND (T9.PROCESS_STATE != 'END' or T9.PROCESS_STATE is null) AND (SPO.COUNTER_ACCT_NO IS NULL OR SPO.MY_ACCT_NO != SPO.COUNTER_ACCT_NO) AND T8.PORTFOLIO_ID IS NOT NULL AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND ((T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE56}, #{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67}, #{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE61}, #{PA_BUSINESS_TYPE62}, #{PA_BUSINESS_TYPE64}, #{PA_BUSINESS_TYPE87}, #{PA_BUSINESS_TYPE125}) and (FPA.PAY_TYPE = '01' or FPA.FINPROD_ID IS NULL)) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE14}, #{PA_BUSINESS_TYPE13}, #{PA_BUSINESS_TYPE15}) AND FPA.PAY_TYPE IS NULL) /*直投：拆入和特殊目的载体拆入首期，存放同业跨托管户卖出、同业借款跨托管户卖出、项目类资产跨托管户卖出、计划类利率型资产跨托管户卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE10}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01},#{TP03}, #{TP04}))/*逐笔划款: 银行间/交易所债券卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE74}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}))/*逐笔划款: 银行间买断式正回购首期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND T4.PS = #{T39} AND SSAI.TRADE_PLACE IN (#{TP01}) AND FPA.PAY_TYPE IS NULL)/*直投：银行间债券行权-赎回*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款的通道交易：银行间/交易所行权-赎回、银行间/交易所行权-回售*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE20}) AND FPA.PAY_TYPE = '01' AND fpt.TYPE_6 = 'H01' AND SSAI.TRADE_PLACE IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款: 银行间/交易所质押式（协议式）正回购首期*/ OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13} ) AND SPO.PS = #{PS01}) )
null) or T1.ACCT_NO in (
#{item}
) AND EXISTS (SELECT 1 from WFL_STL_PAY_ORDERS T6 WHERE T4.TRADE_ID = T6.TRADE_ID AND (T6.COUNTER_ACCT_NO IS NULL OR T6.MY_ACCT_NO != T6.COUNTER_ACCT_NO) #{item})
UNION ALL
SELECT T1.ACCT_NO, nvl(t3.BUSI_ACCT_NO, t1.ACCT_NO) BUSI_ACCT_NO, t1.PORTFOLIO_ID, t2.PORTFOLIO_NAME, T7.MATCH_SEQNO /*多级法人改造 add by caojin 20200701 start */ ,T3.SEQ_NO seqNo /*多级法人改造 add by caojin 20200701 end */ FROM STL_DVP_ORDERS T4 left join PTL_CAPACCT_INFO T1 ON T4.PORTFOLIO_ID = T1.PORTFOLIO_ID and t4.CCY = T1.CCY LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID inner JOIN STL_CAPACCT_INFO T3 ON T3.ACCT_NO = T1.ACCT_NO AND T3.CCY = T1.CCY LEFT JOIN LQD_PIPELINE_MATCH T7 ON T4.ORDER_ID = T7.SYS_TRADE_ID WHERE T4.PS = #{PS01} and t4.order_status='01'
AND T1.ACCT_TYPE = #{A01}
null) or T1.ACCT_NO in (
