select * from ( WITH
PAY_ORDERS AS (SELECT * FROM STL_PAY_ORDERS T5 WHERE T5.ORDER_ID = (SELECT MAX(T52.ORDER_ID) FROM STL_PAY_ORDERS T52 WHERE T5.TRADE_ID = T52.TRADE_ID))
,
WFL_ORDERS AS (SELECT * FROM WFL_STL_PAY_ORDERS T5 WHERE T5.ORDER_ID = (SELECT MAX(T52.ORDER_ID) FROM WFL_STL_PAY_ORDERS T52 WHERE T5.TRADE_ID = T52.TRADE_ID))
SELECT '${sysOrEn}' sysOrEn, T4.TOTLE_TRADE_ID sysSeqNo, '${YES}' IS_TOTAL_TRADE, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, PAY_ORDERS.ORDER_STATUS operateType, NVL(T4.P_TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) bizCode, t5.PA_BUSS_TYPE paBizType, t4.finprod_type2, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID,
nvl(t6.FINPROD_MARKET_ID,T4.FINPROD_ID) as FINPROD_MARKET_ID, nvl(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, PAY_ORDERS.SETTLE_AMT, TO_CHAR(PAY_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') settleDateTheory, TO_CHAR(PAY_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') SETTLE_DATE, t8.COUNTER_NAME counter, t4.CCY, '${STATUS_VALID_05}' statusValid, T4.PS, T4.SEC_MANAGE_ACCT_ID, T5.THEORY_AMT settleAmtTheory, 0 todo, NULL workflowId, NULL wflWorkflowId, T6.PROFIT_TYPE profitType FROM TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TT ON TT.P_TOTLE_TRADE_ID = T4.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T4.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN PAY_ORDERS ON T4.TOTLE_TRADE_ID = PAY_ORDERS.TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY
LEFT JOIN MST_COUNTER_PARTY T8 ON T4.COUNTER_ID = T8.COUNTER_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON TT.TOTLE_TRADE_ID = T9.SYS_TRADE_ID or T4.TOTLE_TRADE_ID = T9.SYS_TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID WHERE ( (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE01}, #{PA_BUSINESS_TYPE02}, #{PA_BUSINESS_TYPE04}, #{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE44}, #{PA_BUSINESS_TYPE45}, #{PA_BUSINESS_TYPE46}, #{PA_BUSINESS_TYPE47}, #{PA_BUSINESS_TYPE48}, #{PA_BUSINESS_TYPE49}, #{PA_BUSINESS_TYPE50}, #{PA_BUSINESS_TYPE38}, #{PA_BUSINESS_TYPE39}, #{PA_BUSINESS_TYPE40}, #{PA_BUSINESS_TYPE41}, #{PA_BUSINESS_TYPE144}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01'))/*非通道或逐笔通道*/ OR (T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE34}, #{PA_BUSINESS_TYPE18}) AND FPA.PAY_TYPE IS NULL) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE77}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}))/*逐笔划款: 银行间买断式逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE51}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}, #{TP03}, #{TP04}) AND fpt.TYPE_6 = 'H01')/*逐笔划款: 银行间/交易所质押式（协议式）逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01') AND SSAI.TRADE_PLACE IN (#{TP01}))/*直投/逐笔划款：银行间债券（收息、还本、到期）*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP03}, #{TP04}))/*逐笔划款: 交易所债券（收息、还本、到期）*/ OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13} ) AND PAY_ORDERS.PS = #{PS01}) )
AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND NOT EXISTS (SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT WHERE TT.P_TRADE_ID = T4.TOTLE_TRADE_ID) AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND (PAY_ORDERS.COUNTER_ACCT_NO IS NULL OR PAY_ORDERS.MY_ACCT_NO != PAY_ORDERS.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL
#{item}
#{item}
AND PAY_ORDERS.ORDER_STATUS = #{operateType}
AND PAY_ORDERS.SETTLE_DATE >= TO_DATE(#{cashDateStart}, 'yyyy-MM-dd')
AND PAY_ORDERS.SETTLE_DATE <= TO_DATE(#{cashDateEnd}, 'yyyy-MM-dd')
and PAY_ORDERS.MY_ACCT_NO = #{acctNo}
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where NVL(TT.TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) = LPM.SYS_TRADE_ID)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where NVL(TT.TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) = LPM.SYS_TRADE_ID)
#{item}
UNION ALL
SELECT '${sysOrEn}' sysOrEn, T3.TRADE_ID sysSeqNo, '${NO}' IS_TOTAL_TRADE, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, PAY_ORDERS.ORDER_STATUS operateType, case when T5.PA_BUSS_TYPE in ('${PA_BUSINESS_TYPE64}','${PA_BUSINESS_TYPE86}','${PA_BUSINESS_TYPE87}') THEN PAY_ORDERS.ORDER_ID WHEN T5.PA_BUSS_TYPE IN ('${PA_BUSINESS_TYPE54}', '${PA_BUSINESS_TYPE56}', '${PA_BUSINESS_TYPE58}', '${PA_BUSINESS_TYPE80}') THEN T3.TOTLE_TRADE_ID ELSE nvl(T3.TOTLE_TRADE_ID, T3.TRADE_ID) END bizCode, t5.PA_BUSS_TYPE paBizType, t3.finprod_type2, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID,
nvl(t6.FINPROD_MARKET_ID,T3.FINPROD_ID) as FINPROD_MARKET_ID, nvl(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, PAY_ORDERS.SETTLE_AMT, TO_CHAR(PAY_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') settleDateTheory, TO_CHAR(PAY_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') SETTLE_DATE, t8.COUNTER_NAME counter, t3.CCY, '${STATUS_VALID_05}' statusValid, T3.PS, T3.SEC_MANAGE_ACCT_ID, NULL settleAmtTheory, 0 todo, NULL workflowId, NULL wflWorkflowId, T6.PROFIT_TYPE profitType FROM TRD_PRODUCT_DEAL T3 LEFT JOIN TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL T5 ON T3.TRADE_ID = T5.TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T3.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN PAY_ORDERS ON T3.TRADE_ID = PAY_ORDERS.TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T3.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T3.CCY
LEFT JOIN MST_COUNTER_PARTY T8 ON T3.COUNTER_ID = T8.COUNTER_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T3.TRADE_ID = T9.SYS_TRADE_ID
LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T3.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T3.CHL_ID = FPA.FINPROD_ID /*通道交易*/ WHERE ((T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE56}, #{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67}, #{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE61}, #{PA_BUSINESS_TYPE62}, #{PA_BUSINESS_TYPE64}, #{PA_BUSINESS_TYPE87}, #{PA_BUSINESS_TYPE125})
) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE14}, #{PA_BUSINESS_TYPE13}, #{PA_BUSINESS_TYPE15}) AND FPA.PAY_TYPE IS NULL) /*直投：拆入和特殊目的载体拆入首期，存放同业跨托管户卖出、同业借款跨托管户卖出、项目类资产跨托管户卖出、计划类利率型资产跨托管户卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE10}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04}))/*逐笔划款: 银行间/交易所债券卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE74}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01}))/*逐笔划款: 银行间买断式正回购首期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND T3.PS = #{T39} AND T3.TRADE_MARKET IN (#{TP01}) AND FPA.PAY_TYPE IS NULL)/*直投：银行间债券行权-赎回*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款的通道交易：银行间/交易所行权-赎回、银行间/交易所行权-回售*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE20}) AND FPA.PAY_TYPE = '01' AND fpt.TYPE_6 = 'H01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款: 银行间/交易所质押式（协议式）正回购首期*/ OR (T3.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13}) AND PAY_ORDERS.PS = #{PS01}) )
AND T3.TRADE_STATUS = #{TRADE_STATUS_01} AND (T3.IS_CANCEL IS NULL OR T3.IS_CANCEL = #{NO}) AND NOT EXISTS (SELECT 1 FROM WFL_TRD_PRODUCT_DEAL TT WHERE TT.P_TRADE_ID = T3.TRADE_ID) AND (PAY_ORDERS.COUNTER_ACCT_NO IS NULL OR PAY_ORDERS.MY_ACCT_NO != PAY_ORDERS.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL
#{item}
#{item}
AND (PAY_ORDERS.ORDER_STATUS is null or PAY_ORDERS.ORDER_STATUS = #{operateType})
AND (PAY_ORDERS.SETTLE_DATE is null or PAY_ORDERS.SETTLE_DATE >= TO_DATE(#{cashDateStart}, 'yyyy-MM-dd'))
AND (PAY_ORDERS.SETTLE_DATE is null or PAY_ORDERS.SETTLE_DATE <= TO_DATE(#{cashDateEnd}, 'yyyy-MM-dd'))
and (PAY_ORDERS.MY_ACCT_NO is null or PAY_ORDERS.MY_ACCT_NO = #{acctNo})
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.TRADE_ID = LPM.SYS_TRADE_ID)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.TRADE_ID = LPM.SYS_TRADE_ID)
#{item}
UNION ALL
/*DVP日间调拨的指令核对*/ SELECT '${sysOrEn}' sysOrEn, T3.ORDER_ID sysSeqNo, 'DVP' IS_TOTAL_TRADE, case when t9.MATCH_SEQNO is null then '${NO}' else '${YES}' end matchStatus, T3.ORDER_STATUS operateType, T3.ORDER_ID bizCode, '${PA_BUSINESS_TYPE81}' paBizType, null finprod_type2, T3.PORTFOLIO_ID, t7.PORTFOLIO_NAME, NULL FINPROD_ID, NULL FINPROD_MARKET_ID, NULL finprodName, T3.SETTLE_AMT, TO_CHAR(T3.SETTLE_DATE, 'yyyy-MM-dd') settleDateTheory, TO_CHAR(T3.SETTLE_DATE, 'yyyy-MM-dd') SETTLE_DATE, NULL counter, t3.CCY, '${STATUS_VALID_05}' statusValid, T3.PS, '${PA_BUSINESS_TYPE81}' SEC_MANAGE_ACCT_ID, NULL settleAmtTheory, 0 todo, NULL workflowId, NULL wflWorkflowId, NULL profitType FROM STL_DVP_ORDERS T3 LEFT JOIN PTL_PORTFOLIO T7 ON T3.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN LQD_PIPELINE_MATCH T9 ON T3.ORDER_ID = T9.SYS_TRADE_ID WHERE T3.PS = #{PS01} and t3.order_status='01'
#{item}
AND T3.ORDER_STATUS = #{operateType}
AND T3.SETTLE_DATE >= TO_DATE(#{cashDateStart}, 'yyyy-MM-dd')
AND T3.SETTLE_DATE <= TO_DATE(#{cashDateEnd}, 'yyyy-MM-dd')
and T3.MY_ACCT_NO = #{acctNo}
AND EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.ORDER_ID = LPM.SYS_TRADE_ID)
AND NOT EXISTS (SELECT 1 FROM LQD_PIPELINE_MATCH LPM where T3.ORDER_ID = LPM.SYS_TRADE_ID)
UNION ALL
SELECT '${sysOrEn}' sysOrEn, T4.TOTLE_TRADE_ID sysSeqNo, '${YES}' IS_TOTAL_TRADE, '${NO}' matchStatus, WFL_ORDERS.ORDER_STATUS operateType, DECODE(TT.P_TRADE_ID, NULL, decode(TT.TOTLE_TRADE_ID, null, NVL(T4.P_TRADE_ID, T4.TOTLE_TRADE_ID), TT.TOTLE_TRADE_ID), TT.P_TRADE_ID) bizCode, t5.PA_BUSS_TYPE paBizType, t4.finprod_type2, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID,
nvl(t6.FINPROD_MARKET_ID,T4.FINPROD_ID) as FINPROD_MARKET_ID, nvl(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, WFL_ORDERS.SETTLE_AMT, TO_CHAR(WFL_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') settleDateTheory, TO_CHAR(WFL_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') SETTLE_DATE, t8.COUNTER_NAME counter, t4.CCY, CASE WHEN T5.PA_BUSS_TYPE =#{PA_BUSINESS_TYPE18} then '${STATUS_VALID_01}' else '${STATUS_VALID_03}' end statusValid, T4.PS, T4.SEC_MANAGE_ACCT_ID, T5.THEORY_AMT settleAmtTheory, CASE WHEN CONCAT(',',CONCAT(T9.NEXT_USER,',')) LIKE CONCAT('%,',CONCAT(#{userName},',%')) THEN 1 ELSE 0 END todo, t4.WORKFLOW_ID workflowId, t9.WORKFLOW_ID wflWorkflowId, T6.PROFIT_TYPE profitType FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID LEFT JOIN WFL_TRD_FIN_PRODUCT_DEAL_TOTAL TT ON T4.P_TOTLE_TRADE_ID = TT.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T4.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN WFL_ORDERS ON T4.TOTLE_TRADE_ID = WFL_ORDERS.TRADE_ID LEFT JOIN MST_COUNTER_PARTY T8 ON T4.COUNTER_ID = T8.COUNTER_ID LEFT JOIN SYS_WFL_BUSINESS_LIST T9 ON
(T4.TOTLE_TRADE_ID = T9.TRADE_ID and t9.action_type in (#{new}, 'modify')) OR
(T4.P_TRADE_ID = T9.TRADE_ID and T9.action_type IN (#{revoke},'delete')) LEFT JOIN SYS_WFL_BUSINESS_NODE T10 ON T9.SEQ_NO = T10.SEQ_NO LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T4.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T4.CCY LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID WHERE ( (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE01}, #{PA_BUSINESS_TYPE02}, #{PA_BUSINESS_TYPE04}, #{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE44}, #{PA_BUSINESS_TYPE45}, #{PA_BUSINESS_TYPE46}, #{PA_BUSINESS_TYPE47}, #{PA_BUSINESS_TYPE48}, #{PA_BUSINESS_TYPE49}, #{PA_BUSINESS_TYPE50}, #{PA_BUSINESS_TYPE38}, #{PA_BUSINESS_TYPE39}, #{PA_BUSINESS_TYPE40}, #{PA_BUSINESS_TYPE41}, #{PA_BUSINESS_TYPE144}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01'))/*非通道或逐笔通道*/ OR (T5.PA_BUSS_TYPE = #{PA_BUSINESS_TYPE34} AND FPA.PAY_TYPE IS NULL) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE77}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}))/*逐笔划款: 银行间买断式逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE51}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP01}, #{TP03}, #{TP04}) AND fpt.TYPE_6 = 'H01')/*逐笔划款: 银行间/交易所质押式（协议式）逆回购到期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND (FPA.FINPROD_ID IS NULL OR FPA.PAY_TYPE = '01') AND SSAI.TRADE_PLACE IN (#{TP01}))/*直投/逐笔划款：银行间债券（收息、还本、到期）*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE37}) AND FPA.PAY_TYPE = '01' AND SSAI.TRADE_PLACE IN (#{TP03}, #{TP04}))/*逐笔划款: 交易所债券（收息、还本、到期）*/ OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13}) AND WFL_ORDERS.PS = #{PS01}) )
AND NOT EXISTS (SELECT 1 FROM SYS_WFL_BUSINESS_NODE TT WHERE TT.SEQ_NO = T9.SEQ_NO AND TT.HIS_NO > T10.HIS_NO) and (T10.NODE_ID IS NULL OR T10.NODE_ID = #{BACK_OPERATOR} OR T10.NODE_ID = #{BACK_CHECKER}) AND (T9.PROCESS_STATE != 'END' or T9.PROCESS_STATE is null) AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND (WFL_ORDERS.COUNTER_ACCT_NO IS NULL OR WFL_ORDERS.MY_ACCT_NO != WFL_ORDERS.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL
#{item}
#{item}
AND WFL_ORDERS.ORDER_STATUS = #{operateType}
AND WFL_ORDERS.SETTLE_DATE >= TO_DATE(#{cashDateStart}, 'yyyy-MM-dd')
AND WFL_ORDERS.SETTLE_DATE <= TO_DATE(#{cashDateEnd}, 'yyyy-MM-dd')
and WFL_ORDERS.MY_ACCT_NO = #{acctNo}
#{item}
UNION ALL
SELECT '${sysOrEn}' sysOrEn, T3.TRADE_ID sysSeqNo, '${NO}' IS_TOTAL_TRADE, '${NO}' matchStatus, WFL_ORDERS.ORDER_STATUS operateType, CASE WHEN T5.PA_BUSS_TYPE IN ('${PA_BUSINESS_TYPE54}', '${PA_BUSINESS_TYPE56}', '${PA_BUSINESS_TYPE58}', '${PA_BUSINESS_TYPE80}') THEN T3.TOTLE_TRADE_ID ELSE nvl(T3.P_TRADE_ID, T3.TRADE_ID) END bizCode, t5.PA_BUSS_TYPE paBizType, t3.finprod_type2, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID,
nvl(t6.FINPROD_MARKET_ID,T3.FINPROD_ID) as FINPROD_MARKET_ID, nvl(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, WFL_ORDERS.SETTLE_AMT, TO_CHAR(WFL_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') settleDateTheory, TO_CHAR(WFL_ORDERS.SETTLE_DATE, 'yyyy-MM-dd') SETTLE_DATE, t8.COUNTER_NAME counter, t3.CCY, CASE WHEN T5.PA_BUSS_TYPE IN (
#{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE83}, #{PA_BUSINESS_TYPE56},#{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67},#{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE125} ) then '${STATUS_VALID_01}' else '${STATUS_VALID_03}' end statusValid, T3.PS, T3.SEC_MANAGE_ACCT_ID, NULL settleAmtTheory, CASE WHEN CONCAT(',',CONCAT(T9.NEXT_USER,',')) LIKE CONCAT('%,',CONCAT(#{userName},',%')) THEN 1 ELSE 0 END todo, t4.WORKFLOW_ID workflowId, t9.WORKFLOW_ID wflWorkflowId, T6.PROFIT_TYPE profitType FROM WFL_TRD_PRODUCT_DEAL T3 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T4 ON T3.TRADE_ID = T4.TRADE_ID LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL T5 ON T3.TRADE_ID = T5.TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T3.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN WFL_ORDERS ON T3.TRADE_ID = WFL_ORDERS.TRADE_ID
LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T3.SEC_MANAGE_ACCT_ID AND SSAI.TRD_ACCT_CCY = T3.CCY
LEFT JOIN MST_COUNTER_PARTY T8 ON T3.COUNTER_ID = T8.COUNTER_ID LEFT JOIN SYS_WFL_BUSINESS_LIST T9 ON
(T3.TRADE_ID = T9.TRADE_ID and t9.action_type in (#{new}, 'modify')) OR
(T3.P_TRADE_ID = T9.TRADE_ID and T9.action_type IN (#{revoke},'delete')) LEFT JOIN SYS_WFL_BUSINESS_NODE T10 ON T9.SEQ_NO = T10.SEQ_NO LEFT JOIN WFL_TRD_PRODUCT_DEAL PT ON (T3.B_TRADE_ID = PT.P_TRADE_ID or t3.B_TRADE_ID = pt.TRADE_ID) LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T3.TRADE_ID LEFT JOIN FIN_PRODUCT_ADD FPA ON T3.CHL_ID = FPA.FINPROD_ID /*通道交易*/ WHERE ((T5.PA_BUSS_TYPE IN (
#{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE56}, #{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67}, #{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE61}, #{PA_BUSINESS_TYPE62}, #{PA_BUSINESS_TYPE64}, #{PA_BUSINESS_TYPE87}, #{PA_BUSINESS_TYPE125})
) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE14}, #{PA_BUSINESS_TYPE13}, #{PA_BUSINESS_TYPE83}, #{PA_BUSINESS_TYPE15}) AND FPA.PAY_TYPE IS NULL) /*直投：拆入和特殊目的载体拆入首期，存放同业跨托管户卖出、同业借款跨托管户卖出、项目类资产跨托管户卖出、计划类利率型资产跨托管户卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE10}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04}))/*逐笔划款: 银行间/交易所债券卖出*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE74}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01}))/*逐笔划款: 银行间买断式正回购首期*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND T3.PS = #{T39} AND T3.TRADE_MARKET IN (#{TP01}) AND FPA.PAY_TYPE IS NULL)/*直投：银行间债券行权-赎回*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE11}) AND FPA.PAY_TYPE = '01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款的通道交易：银行间/交易所行权-赎回、银行间/交易所行权-回售*/ OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE20}) AND FPA.PAY_TYPE = '01' AND fpt.TYPE_6 = 'H01' AND T3.TRADE_MARKET IN (#{TP01},#{TP03}, #{TP04})) /*逐笔划款: 银行间/交易所质押式（协议式）正回购首期*/ OR (T3.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13} ) AND WFL_ORDERS.PS = #{PS01}) )
AND (T5.PA_BUSS_TYPE NOT IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE83}, #{PA_BUSINESS_TYPE56}, #{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67}, #{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE125} ) OR PT.TRADE_ID IS NULL)
AND T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE83}, #{PA_BUSINESS_TYPE56},#{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67},#{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE125} )
AND (T5.PA_BUSS_TYPE NOT IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE83}, #{PA_BUSINESS_TYPE56},#{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67},#{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE125} ) OR T3.WORKFLOW_ID IS NULL)/*待处理数据的工作流代码为空*/ AND NOT EXISTS (SELECT 1 FROM SYS_WFL_BUSINESS_NODE TT WHERE TT.SEQ_NO = T9.SEQ_NO AND TT.HIS_NO > T10.HIS_NO) and (T10.NODE_ID IS NULL OR T10.NODE_ID = #{BACK_OPERATOR} OR T10.NODE_ID = #{BACK_CHECKER}) AND (T9.PROCESS_STATE != 'END' or T9.PROCESS_STATE is null) AND (T3.IS_CANCEL IS NULL OR T3.IS_CANCEL = #{NO}) AND (WFL_ORDERS.COUNTER_ACCT_NO IS NULL OR WFL_ORDERS.MY_ACCT_NO != WFL_ORDERS.COUNTER_ACCT_NO) AND T4.PORTFOLIO_ID IS NOT NULL
#{item}
#{item}
AND WFL_ORDERS.ORDER_STATUS = #{operateType}
AND WFL_ORDERS.SETTLE_DATE >= TO_DATE(#{cashDateStart}, 'yyyy-MM-dd')
AND WFL_ORDERS.SETTLE_DATE <= TO_DATE(#{cashDateEnd}, 'yyyy-MM-dd')
and (T5.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE58}, #{PA_BUSINESS_TYPE54}, #{PA_BUSINESS_TYPE83}, #{PA_BUSINESS_TYPE56},#{PA_BUSINESS_TYPE80}, #{PA_BUSINESS_TYPE66}, #{PA_BUSINESS_TYPE67},#{PA_BUSINESS_TYPE73}, #{PA_BUSINESS_TYPE68}, #{PA_BUSINESS_TYPE125} ) or WFL_ORDERS.MY_ACCT_NO = #{acctNo})
#{item}
) order by SETTLE_AMT asc
